def make_correct():
    class RoutingCache:
        def __init__(self):
            self._values = {}

        def put(self, tenant_id, ticket_id, queue):
            self._values[(tenant_id, ticket_id)] = queue

        def get(self, tenant_id, ticket_id):
            return self._values.get((tenant_id, ticket_id))

        def invalidate(self, tenant_id, ticket_id):
            self._values.pop((tenant_id, ticket_id), None)

    return RoutingCache


def make_mutant_c_ticket_id_only():
    # Keys by ticket_id alone: tenants collide on put/get AND invalidate.
    class RoutingCache:
        def __init__(self):
            self._values = {}

        def put(self, tenant_id, ticket_id, queue):
            self._values[ticket_id] = queue

        def get(self, tenant_id, ticket_id):
            return self._values.get(ticket_id)

        def invalidate(self, tenant_id, ticket_id):
            self._values.pop(ticket_id, None)

    return RoutingCache


def make_mutant_d_invalidate_scans_all_tenants():
    # put/get are correctly tenant-scoped, but invalidate wipes the ticket_id
    # across every tenant (a plausible "helper forgot the tenant filter" bug).
    class RoutingCache:
        def __init__(self):
            self._values = {}

        def put(self, tenant_id, ticket_id, queue):
            self._values[(tenant_id, ticket_id)] = queue

        def get(self, tenant_id, ticket_id):
            return self._values.get((tenant_id, ticket_id))

        def invalidate(self, tenant_id, ticket_id):
            for key in list(self._values):
                if key[1] == ticket_id:
                    self._values.pop(key, None)

    return RoutingCache


def run_tests(RoutingCache, label):
    results = {}

    def test_round_trip():
        cache = RoutingCache()
        cache.put("tenant-a", "T-1", "billing")
        assert cache.get("tenant-a", "T-1") == "billing"

    def test_get_missing_returns_none():
        cache = RoutingCache()
        assert cache.get("tenant-a", "does-not-exist") is None

    def test_isolates_same_ticket_id_across_tenants():
        cache = RoutingCache()
        cache.put("tenant-a", "T-1", "billing")
        cache.put("tenant-b", "T-1", "bug")
        assert cache.get("tenant-a", "T-1") == "billing"
        assert cache.get("tenant-b", "T-1") == "bug"

    def test_invalidate_does_not_cross_tenant_boundaries():
        cache = RoutingCache()
        cache.put("tenant-a", "T-1", "billing")
        cache.put("tenant-b", "T-1", "bug")
        cache.invalidate("tenant-a", "T-1")
        assert cache.get("tenant-a", "T-1") is None
        assert cache.get("tenant-b", "T-1") == "bug"

    def test_invalidate_missing_entry_is_a_noop():
        cache = RoutingCache()
        cache.invalidate("tenant-a", "does-not-exist")

