    def test_walks_all_rows_without_repeat_or_skip():
        rows = [
            TicketRow("T-1", _iso(1)),
            TicketRow("T-2", _iso(2)),
            TicketRow("T-3", _iso(2)),
            TicketRow("T-4", _iso(2)),
            TicketRow("T-5", _iso(3)),
            TicketRow("T-6", _iso(4)),
            TicketRow("T-7", _iso(5)),
        ]
        expected_order = [r.ticket_id for r in sorted(rows, key=lambda r: (r.created_at, r.ticket_id))]
        seen = []
        cursor = None
        for _ in range(len(rows) + 2):
            page, cursor = page_after(rows, cursor, 2)
            seen.extend(row.ticket_id for row in page)
            if cursor is None:
                break
        assert seen == expected_order

    def test_returns_each_tied_row_exactly_once():
        rows = [
            TicketRow("T-3", _iso(1)),
            TicketRow("T-1", _iso(1)),
            TicketRow("T-2", _iso(1)),
        ]
        seen = []
        cursor = None
        for _ in range(5):
            page, cursor = page_after(rows, cursor, 1)
            seen.extend(row.ticket_id for row in page)
            if cursor is None:
