            results[fn.__name__] = "pass"
        except AssertionError as e:
            results[fn.__name__] = f"FAIL: {e}"
        except Exception as e:
            results[fn.__name__] = f"ERROR: {e!r}"

    print(f"--- {label} ---")
    for name, outcome in results.items():
